16317	void Plater::send_gcode_legacy(int plate_idx, Export3mfProgressFn proFn)
16318	{
16319	    // if physical_printer is selected, send gcode for this printer
16320	    // DynamicPrintConfig* physical_printer_config = wxGetApp().preset_bundle->physical_printers.get_selected_printer_config();
16321	    DynamicPrintConfig* physical_printer_config = &Slic3r::GUI::wxGetApp().preset_bundle->printers.get_edited_preset().config;
16322	    if (! physical_printer_config || p->model.objects.empty())
16323	        return;
16324	
16325	    PrintHostJob upload_job(physical_printer_config);
16326	    if (upload_job.empty())
16327	        return;
16328	
16329	    // Orca: the use_3mf printer option makes us send a .gcode.3mf to the printer
16330	    const auto* use_3mf_opt = physical_printer_config->option<ConfigOptionBool>("use_3mf");
16331	    const bool  use_3mf     = use_3mf_opt != nullptr && use_3mf_opt->value;
16332	
16333	    upload_job.upload_data.use_3mf = use_3mf;
16334	    // Orca: the concrete plate to export/send (PLATE_CURRENT_IDX resolves to the current plate).
16335	    const int resolved_plate_idx = plate_idx == PLATE_CURRENT_IDX ? get_partplate_list().get_curr_plate_index() : plate_idx;
16336	
16337	    // Obtain default output path
16338	    fs::path default_output_file;
16339	    try {
16340	        // Update the background processing, so that the placeholder parser will get the correct values for the ouput file template.
16341	        // Also if there is something wrong with the current configuration, a pop-up dialog will be shown and the export will not be performed.
16342	        unsigned int state = this->p->update_restart_background_process(false, false);
16343	        if (state & priv::UPDATE_BACKGROUND_PROCESS_INVALID)
16344	            return;
16345	        default_output_file = this->p->background_process.output_filepath_for_project(
16346	            into_path(this->p->get_project_filename(".3mf")));
16347	    } catch (const Slic3r::PlaceholderParserError& ex) {
16348	        // Show the error with monospaced font.
16349	        show_error(this, ex.what(), true);
16350	        return;
16351	    } catch (const std::exception& ex) {
16352	        show_error(this, ex.what(), false);
16353	        return;
16354	    }
16355	    default_output_file = fs::path(Slic3r::fold_utf8_to_ascii(default_output_file.string()));
16356	    if (use_3mf) {
16357	        // Orca: a gcode-in-3mf bundle is named ".gcode.3mf" (matching "Export plate sliced file")
16358	        default_output_file.replace_extension(".gcode.3mf");
16359	    }
16360	
16361	    // Repetier specific: Query the server for the list of file groups.
16362	    wxArrayString groups;
16363	    {
16364	        wxBusyCursor wait;
16365	        upload_job.printhost->get_groups(groups);
16366	    }
16367	
16368	    // PrusaLink specific: Query the server for the list of file groups.
16369	    wxArrayString storage_paths;
16370	    wxArrayString storage_names;
16371	    {
16372	        wxBusyCursor wait;
16373	        try {
16374	            upload_job.printhost->get_storage(storage_paths, storage_names);
16375	        } catch (const Slic3r::IOError& ex) {
16376	            show_error(this, ex.what(), false);
16377	            return;
16378	        }
16379	    }
16380	
16381	    {
16382	        auto        preset_bundle = wxGetApp().preset_bundle;
16383	        auto        config        = get_app_config();
16384	
16385	        const auto host_type_opt        = physical_printer_config->option<ConfigOptionEnum<PrintHostType>>("host_type");
16386	        const auto host_type            = host_type_opt != nullptr ? host_type_opt->value : htElegooLink;
16387	        const auto* ff_serial_opt       = physical_printer_config->option<ConfigOptionString>("flashforge_serial_number");
16388	        const auto* ff_code_opt         = physical_printer_config->option<ConfigOptionString>("printhost_apikey");
16389	        const bool flashforge_local_api = host_type == htFlashforge && ff_serial_opt != nullptr && !ff_serial_opt->value.empty() &&
16390	                                          ff_code_opt != nullptr && !ff_code_opt->value.empty();
16391	
16392	        std::unique_ptr<PrintHostSendDialog> pDlg;
16393	        if (host_type == htElegooLink) {
16394	            pDlg = std::make_unique<ElegooPrintHostSendDialog>(default_output_file, upload_job.printhost->get_post_upload_actions(), groups,
16395	                                                               storage_paths, storage_names,
16396	                                                               config->get_bool("open_device_tab_post_upload"));
16397	        } else if (host_type == htCrealityPrint) {
16398	            pDlg = std::make_unique<CrealityPrintHostSendDialog>(default_output_file, upload_job.printhost->get_post_upload_actions(), groups,
16399	                                                                 storage_paths, storage_names,
16400	                                                                 config->get_bool("open_device_tab_post_upload"),
16401	                                                                 upload_job.printhost.get());
16402	        } else if (flashforge_local_api) {
16403	            auto* flashforge_host = dynamic_cast<Flashforge*>(upload_job.printhost.get());
16404	            if (flashforge_host == nullptr) {
16405	                show_error(this, _L("Flashforge host is not available."), false);
16406	                return;
16407	            }
16408	
16409	            std::vector<FlashforgeMaterialSlot> slots;
16410	            bool                                supports_material_station = false;
16411	            {
16412	                wxBusyCursor wait;
16413	                wxString     msg;
16414	                if (!flashforge_host->fetch_material_slots(slots, &supports_material_station, msg)) {
16415	                    show_error(this, msg.empty() ? _L("Unable to log in to the Flashforge printer.") : msg, false);
16416	                    return;
16417	                }
16418	            }
16419	
16420	            std::vector<FilamentInfo> project_filaments;
16421	            PlateDataPtrs               plate_data_list;
16422	            DynamicPrintConfig          cfg                 = wxGetApp().preset_bundle->full_config();
16423	            const auto*                 filament_color      = dynamic_cast<const ConfigOptionStrings*>(cfg.option("filament_colour"));
16424	            const auto*                 filament_id_opt     = dynamic_cast<const ConfigOptionStrings*>(cfg.option("filament_ids"));
16425	            auto enrich_project_filaments = [&](std::vector<FilamentInfo>& filaments) {
16426	                for (auto& filament : filaments) {
16427	                    if (filament.id < 0)
16428	                        continue;
16429	
16430	                    std::string display_filament_type;
16431	                    try {
16432	                        filament.type = cfg.get_filament_type(display_filament_type, filament.id);
16433	                    } catch (...) {
16434	                    }
16435	
16436	                    if (filament.type.empty())
16437	                        filament.type = display_filament_type;
16438	                    if (filament.type.empty())
16439	                        filament.type = "Unknown";
16440	
16441	                    filament.filament_id = filament_id_opt ? filament_id_opt->get_at(static_cast<size_t>(filament.id)) : "";
16442	                    filament.color       = filament_color ? filament_color->get_at(static_cast<size_t>(filament.id)) : "#FFFFFF";
16443	                    if (filament.color.empty())
16444	                        filament.color = "#FFFFFF";
16445	                }
16446	            };
16447	
16448	            p->partplate_list.store_to_3mf_structure(plate_data_list, true, plate_idx);
16449	            PlateData* selected_plate_data = (resolved_plate_idx >= 0 && resolved_plate_idx < static_cast<int>(plate_data_list.size())) ? plate_data_list[resolved_plate_idx] : nullptr;
16450	            if (selected_plate_data == nullptr && !plate_data_list.empty())
16451	                selected_plate_data = plate_data_list.front();
16452	
16453	            if (selected_plate_data != nullptr)
16454	                project_filaments = selected_plate_data->slice_filaments_info;
16455	
16456	            if (project_filaments.empty()) {
16457	                if (PartPlate* plate = get_partplate_list().get_plate(resolved_plate_idx); plate != nullptr)
16458	                    project_filaments = plate->get_slice_filaments_info();
16459	            }
16460	
16461	            if (!project_filaments.empty())
16462	                enrich_project_filaments(project_filaments);
16463	            release_PlateData_list(plate_data_list);
16464	
16465	            pDlg = std::make_unique<FlashforgePrintHostSendDialog>(default_output_file, upload_job.printhost->get_post_upload_actions(), groups,
16466	                                                                   storage_paths, storage_names,
16467	                                                                   config->get_bool("open_device_tab_post_upload"),
16468	                                                                   flashforge_host,
16469	                                                                   supports_material_station,
16470	                                                                   std::move(slots),
16471	                                                                   project_filaments);
16472	        } else {
16473	            pDlg = std::make_unique<PrintHostSendDialog>(default_output_file, upload_job.printhost->get_post_upload_actions(), groups,
16474	                                                         storage_paths, storage_names, config->get_bool("open_device_tab_post_upload"));
16475	        }
16476	
16477	        pDlg->init();
16478	        if (pDlg->ShowModal() != wxID_OK) {
16479	            return;
16480	        }
16481	
16482	        config->set_bool("open_device_tab_post_upload", pDlg->switch_to_device_tab());
16483	        // PrintHostUpload upload_data;
16484	        upload_job.switch_to_device_tab    = pDlg->switch_to_device_tab();
16485	        upload_job.upload_data.upload_path = pDlg->filename();
16486	        upload_job.upload_data.post_action = pDlg->post_action();
16487	        upload_job.upload_data.group       = pDlg->group();
16488	        upload_job.upload_data.storage     = pDlg->storage();
16489	        upload_job.upload_data.extended_info = pDlg->extendedInfo();
16490	        // Orca: gcode inside a .gcode.3mf is index-coded (Metadata/plate_<N>.gcode) and a bundle may
16491	        // carry several of them, so the upload must name which plate to print via a 1-based plateindex.
16492	        // Even a single-plate bundle needs it, since its gcode entry is still indexed. The host upload
16493	        // forwards the field and servers that don't use it ignore it. "All plates" points at the
16494	        // current plate — the bundle still carries every plate's gcode.
16495	        if (use_3mf) {
16496	            const int plateindex = (plate_idx == PLATE_ALL_IDX ? get_partplate_list().get_curr_plate_index() : resolved_plate_idx) + 1;
16497	            upload_job.upload_data.extended_info["plateindex"] = std::to_string(plateindex);
16498	        }
16499	    }
16500	
16501	    // Show "Is printer clean" dialog for PrusaConnect - Upload and print.
16502	    if (std::string(upload_job.printhost->get_name()) == "PrusaConnect" && upload_job.upload_data.post_action == PrintHostPostUploadAction::StartPrint) {
16503	        GUI::MessageDialog dlg(nullptr, _L("Is the printer ready? Is the print sheet in place, empty and clean?"), _L("Upload and Print"), wxOK | wxCANCEL);
16504	        if (dlg.ShowModal() != wxID_OK)
16505	            return;
16506	    }
16507	
16508	    if (use_3mf) {
16509	        // Process gcode
16510	        const int result = send_gcode(resolved_plate_idx, nullptr);
16511	
16512	        if (result < 0) {
16513	            wxString msg = _L("Abnormal print file data. Please slice again");
