13693	void Plater::load_gcode(const wxString& filename)
13694	{
13695	    BOOST_LOG_TRIVIAL(trace) << __FUNCTION__ << __LINE__ << " entry and filename: " << filename;
13696	    BOOST_LOG_TRIVIAL(info) << __FUNCTION__;
13697	    if (! is_gcode_file(into_u8(filename))
13698	        || (m_last_loaded_gcode == filename && m_only_gcode)
13699	        )
13700	        return;
13701	
13702	    m_last_loaded_gcode = filename;
13703	
13704	    // BSS: create a new project when load_gcode, force close previous one
13705	    if (new_project(false, true) != wxID_YES)
13706	        return;
13707	
13708	    m_only_gcode = true;
13709	
13710	    // cleanup view before to start loading/processing
13711	    //BBS: update gcode to current partplate's
13712	    GCodeProcessorResult* current_result = p->partplate_list.get_current_slice_result();
13713	    Print& current_print = p->partplate_list.get_current_fff_print();
13714	    //BBS:already reset in new_project
13715	    //current_result->reset();
13716	    //p->gcode_result.reset();
13717	    //reset_gcode_toolpaths();
13718	    p->preview->reload_print(m_only_gcode);
13719	    wxGetApp().mainframe->select_tab(MainFrame::tpPreview);
13720	    p->set_current_panel(p->preview, true);
13721	    p->get_current_canvas3D()->render();
13722	    //p->notification_manager->bbl_show_plateinfo_notification(into_u8(_L("Preview only mode for gcode file.")));
13723	
13724	    wxBusyCursor wait;
13725	
13726	    // process gcode
13727	    GCodeProcessor processor;
13728	    processor.init_filament_maps_and_nozzle_type_when_import_only_gcode();
13729	    try
13730	    {
13731	        GCodeProcessor::s_IsBBLPrinter = wxGetApp().preset_bundle->is_bbl_vendor();
13732	        processor.process_file(filename.ToUTF8().data());
13733	    }
13734	    catch (const std::exception& ex)
13735	    {
13736	        show_error(this, ex.what());
13737	        return;
13738	    }
13739	    *current_result = std::move(processor.extract_result());
13740	    //current_result->filename = filename;
13741	
13742	    BedType bed_type = current_result->bed_type;
13743	    if (bed_type != BedType::btCount) {
13744	        DynamicPrintConfig &proj_config = wxGetApp().preset_bundle->project_config;
13745	        proj_config.set_key_value("curr_bed_type", new ConfigOptionEnum<BedType>(bed_type));
13746	        on_bed_type_change(bed_type);
13747	    }
13748	
13749	    current_print.apply(this->model(), wxGetApp().preset_bundle->full_config());
13750	
13751	    current_print.apply_config_for_render(processor.export_config_for_render());
13752	
13753	    //BBS: add cost info when drag in gcode
13754	    auto& ps = current_result->print_statistics;
13755	    double total_cost = 0.0;
13756	    for (auto volume : ps.total_volumes_per_extruder) {
13757	        size_t extruder_id = volume.first;
13758	        double density = current_result->filament_densities.at(extruder_id);
13759	        double cost = current_result->filament_costs.at(extruder_id);
13760	        double weight = volume.second * density * 0.001;
13761	        total_cost += weight * cost * 0.001;
13762	    }
13763	    current_print.print_statistics().total_cost = total_cost;
13764	
13765	    current_print.set_gcode_file_ready();
13766	
13767	    // show results
13768	    p->preview->reload_print(m_only_gcode);
13769	    //BBS: zoom to bed 0 for gcode preview
13770	    //p->preview->get_canvas3d()->zoom_to_gcode();
13771	    p->preview->get_canvas3d()->zoom_to_plate(0);
13772	
13773	    if (p->preview->get_canvas3d()->get_gcode_layers_zs().empty()) {
13774	        MessageDialog(this, _L("The selected file") + ":\n" + filename + "\n" + _L("does not contain valid G-code."),
13775	            wxString(GCODEVIEWER_APP_NAME) + " - " + _L("Error occurs while loading G-code file"), wxCLOSE | wxICON_WARNING | wxCENTRE).ShowModal();
13776	        set_project_filename(DEFAULT_PROJECT_NAME);
13777	    } else {
13778	        set_project_filename(filename);
13779	    }
13780	
13781	    // Orca: Fix crash when loading gcode file multiple times
13782	    if (m_only_gcode) {
13783	        p->view3D->get_canvas3d()->remove_raycasters_for_picking(SceneRaycaster::EType::Bed);
13784	    }
13785	
13786	    p->main_frame->update_slice_print_status(MainFrame::eEventPlateUpdate, false, false); //20250416 ban gcode to send print
13787	}
