227	{
228	    // bg thread entry point
229	
230	    try {
231	        // Pick up jobs from the job channel:
232	        while (! bg_exit) {
233	            auto job = channel_jobs.pop();   // Sleeps in a cond var if there are no jobs
234	            if (job.empty()) {
235	                // This happens when the thread is being stopped
236	                break;
237	            }
238	
239	            source_to_remove = job.upload_data.source_path;
240	
241	            BOOST_LOG_TRIVIAL(debug) << boost::format("PrintHostJobQueue/bg_thread: Received job: [%1%]: `%2%` -> `%3%`, cancelled: %4%")
242	                % job_id
243	                % job.upload_data.upload_path
244	                % job.printhost->get_host()
245	                % job.cancelled;
246	
247	            if (! job.cancelled) {
248	                perform_job(std::move(job));
249	            }
250	
251	            remove_source();
252	            job_id++;
253	        }
254	    } catch (const std::exception &e) {
255	        emit_error(e.what());
256	    }
257	
258	    // Cleanup leftover files, if any
259	    remove_source();
260	    auto jobs = channel_jobs.lock_rw();
261	    for (const PrintHostJob &job : *jobs) {
262	        remove_source(job.upload_data.source_path);
263	    }
264	}
