140	void GcodeHistoryRecorder::unhook_print_host_queue()
141	{
142	    // A queue made again since is not this recorder's to change.
143	    if (m_print_host_queue != nullptr && m_print_host_queue == &wxGetApp().printhost_job_queue())
144	        m_print_host_queue->set_enqueue_observer({});
145	    m_print_host_queue = nullptr;
146	    if (m_print_host_dialog) {
147	        m_print_host_dialog->Unbind(EVT_PRINTHOST_PROGRESS, &GcodeHistoryRecorder::on_print_host_progress, this);
148	        m_print_host_dialog->Unbind(EVT_PRINTHOST_ERROR, &GcodeHistoryRecorder::on_print_host_ended, this);
149	        m_print_host_dialog->Unbind(EVT_PRINTHOST_CANCEL, &GcodeHistoryRecorder::on_print_host_ended, this);
150	    }
151	    m_print_host_dialog = nullptr;
152	    m_uploads.clear();
153	}
