119	void GcodeHistoryRecorder::hook_print_host_queue()
120	{
121	    PrintHostJobQueue* queue = &wxGetApp().printhost_job_queue();
122	    if (queue == m_print_host_queue)
123	        return;
124	    unhook_print_host_queue();
125	    m_print_host_queue = queue;
126	    // The upload queue runs on its own thread: the observer copies what it
127	    // needs and hands it to the GUI thread.
128	    m_print_host_queue->set_enqueue_observer([this](std::size_t id, const PrintHostJob& job) {
129	        CallAfter([this, id, host = job.printhost->get_host(), file_name = into_u8(from_path(job.upload_data.upload_path.filename())),
130	                   start = job.upload_data.post_action == PrintHostPostUploadAction::StartPrint] {
131	            on_print_host_queued(id, host, file_name, start);
132	        });
133	    });
134	    m_print_host_dialog = wxGetApp().mainframe->printhost_queue_dlg();
135	    m_print_host_dialog->Bind(EVT_PRINTHOST_PROGRESS, &GcodeHistoryRecorder::on_print_host_progress, this);
136	    m_print_host_dialog->Bind(EVT_PRINTHOST_ERROR, &GcodeHistoryRecorder::on_print_host_ended, this);
137	    m_print_host_dialog->Bind(EVT_PRINTHOST_CANCEL, &GcodeHistoryRecorder::on_print_host_ended, this);
138	}
